const grid = [
  ["Smith", "John", "$50.00"],
  ["Bach", "Frank", "$51.00"],
];

for (let i = 0; i < grid.length; i++) {
  const row = grid[i];
  let line = `row ${i}:`;
  for (let j = 0; j < row.length; j++) {
    line += ` [${j}]${row[j]}`;
  }
  console.log(line);
}

const table: string[][] = [
  ["Smith", "John", "$50.00"],
  ["Bach", "Frank", "$51.00"],
];

console.log("rows:      ", table.length);
console.log("cells/row: ", table[0].length);
console.log("row 1 cell 2:", table[1][2]);
console.log("whole thing:", JSON.stringify(table));

// A row is just an array, so array methods work on it
console.log("first column:", table.map((row) => row[0]));

const prices = ["$50.00", "$51.00", "$100.00"];

// map: transform each item
const numbers = prices.map((p) => Number(p.replace("$", "")));
console.log("with map: ", numbers);

// push: the long way round, same answer
const collected: number[] = [];
for (let i = 0; i < prices.length; i++) {
  collected.push(Number(prices[i].replace("$", "")));
}
console.log("with push:", collected);

console.log("total:", numbers.reduce((sum, n) => sum + n, 0));

// Plain TypeScript version of the same idea — no browser involved yet.
function columnOf(table: string[][], index: number): string[] {
  return table.map((row) => row[index]);
}

const data: string[][] = [
  ["Smith", "John", "$50.00"],
  ["Bach", "Frank", "$51.00"],
  ["Conway", "Tim", "$50.00"],
];

console.log("last names: ", columnOf(data, 0));
console.log("first names:", columnOf(data, 1));
console.log("dues:       ", columnOf(data, 2));

