import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 8 Day 1.1, concept 2.

await writeProjectFile("week8/generated/day3-scrape-tables.spec.ts", `// Week 8, Day 3 — pulling a whole table out of a page.
//
// Written by a cell in week8/day3_2.ipynb. Run it yourself:
//   npx playwright test week8/generated/day3-scrape-tables.spec.ts
import { test, expect, type Page } from "@playwright/test";

const URL = "https://the-internet.herokuapp.com/tables";

/**
 * Read every body row of a table into an array of arrays.
 *
 * The selector is a parameter, which is the whole difference between a snippet
 * and a tool: the same function reads #table1, #table2, or any table you meet
 * later, without being edited.
 */
async function scrapeTable(page: Page, tableSelector: string): Promise<string[][]> {
  return page.$$eval(\`\${tableSelector} tbody tr\`, (rows) =>
    rows.map((row) =>
      Array.from(row.querySelectorAll("td")).map((cell) =>
        (cell as HTMLElement).innerText.replace(/\\s+/g, " ").trim()
      )
    )
  );
}

test.describe("Scraping a web table", () => {
  test("Step 1 — read every row out of the first table", async ({ page }) => {
    await page.goto(URL);

    const rows = await scrapeTable(page, "#table1");

    expect(rows).toHaveLength(4);
    expect(rows[0]).toEqual([
      "Smith",
      "John",
      "jsmith@gmail.com",
      "$50.00",
      "http://www.jsmith.com",
      "edit delete",
    ]);
    expect(rows[3][0]).toBe("Conway");
  });

  test("Step 2 — the same function reads the second table, unchanged", async ({ page }) => {
    await page.goto(URL);

    const one = await scrapeTable(page, "#table1");
    const two = await scrapeTable(page, "#table2");

    // Different markup, same data — which is exactly why the page exists.
    expect(two).toHaveLength(4);
    expect(two).toEqual(one);
  });

  test("Step 3 — $ finds one element, $$ finds all of them", async ({ page }) => {
    await page.goto(URL);

    const single = await page.$("#table1 tbody tr");
    const all = await page.$$("#table1 tbody tr");

    expect(single).not.toBeNull(); // just the first match
    expect(all).toHaveLength(4); // every match
  });

  test("Step 4 — pull one column out and check it is sorted", async ({ page }) => {
    await page.goto(URL);

    // Dues look like "$50.00", so strip the $ before comparing as numbers.
    const dues = (await scrapeTable(page, "#table1")).map((row) => Number(row[3].replace("$", "")));

    expect(dues).toEqual([50, 51, 100, 50]);
    // Deliberately NOT sorted — proving the scrape read real order, not a guess.
    expect([...dues].sort((a, b) => a - b)).not.toEqual(dues);
  });

  test("Step 5 — the modern way: a locator instead of $$eval", async ({ page }) => {
    await page.goto(URL);

    const rowLocator = page.locator("#table1 tbody tr");

    // Locators auto-wait and re-query; $$eval takes one snapshot immediately.
    await expect(rowLocator).toHaveCount(4);

    const firstCells = await rowLocator.first().locator("td").allInnerTexts();
    expect(firstCells[0]).toBe("Smith");
  });
});
`);

await runSpec("week8/generated/day3-scrape-tables.spec.ts");

import type { Page } from "npm:playwright";

/** One row per table row, keyed by header text. No assertions — the test decides. */
async function readTable(p: Page, tableSelector: string): Promise<Record<string, string>[]> {
  const headers = (await p.locator(`${tableSelector} thead th`).allInnerTexts())
    .map((h) => h.replace(/\s+/g, " ").trim());

  const rows = await p.$$eval(`${tableSelector} tbody tr`, (trs) =>
    trs.map((tr) =>
      Array.from(tr.querySelectorAll("td")).map((td) =>
        (td as HTMLElement).innerText.replace(/\s+/g, " ").trim()
      )
    )
  );

  // Zip each row against the headers.
  return rows.map((cells) => {
    const record: Record<string, string> = {};
    headers.forEach((header, i) => {
      record[header] = cells[i] ?? "";
    });
    return record;
  });
}

